// 当前批准重新校验后冻结真实接受时刻；预留或占用失败必须丢弃整个共同候选。
#include "governance_task_admission.hpp"
#include <limits>
namespace hanmo::resident {
Outcome<GovernanceAuthorityApproval> preview_governance_acceptance(const CommonStore& common,const GovernanceTaskState& governance,const GovernanceAuthorityRead& authority,const StableId& executor,const StableId& fact_id,Integer expected_revision){
    if(expected_revision!=common.revision())return {false,{},common_failure("StaleWorldRevision").error};
    const auto* actor=common.actor(executor);if(!actor)return {false,{},common_failure("UnknownActor",executor).error};if(!actor->alive||!actor->available||actor->hp<=0)return {false,{},common_failure("ActorUnavailable",executor).error};if(!actor->action_id.empty())return {false,{},common_failure("ActorBusy",executor).error};
    auto approved=authority.governance_authority_for_acceptance(fact_id,executor,expected_revision);if(!approved.ok)return approved;const auto& a=approved.value;const auto* header=common.state().facts.find(fact_id);
    if(a.authority_fact_id!=fact_id||a.executor_actor_id!=executor||!header||header->kind!=governance_authority_fact_kind||header->domain!="politics"||a.organization_id.empty()||a.jurisdiction_id.empty()||a.site_id.empty()||a.rule_id.empty()||a.rule_version.empty()||a.relief_policy_id.empty()||a.public_wallet_id.empty()||a.public_inventory_id.empty()||a.grain_item_id.empty())return {false,{},common_failure("InvalidGovernanceAuthoritySource",fact_id,ErrorKind::internal).error};
    if(a.issued_tick>common.tick()||a.offer_expires_tick<common.tick())return {false,{},common_failure("GovernanceAuthorityExpired",fact_id).error};
    if(a.work_ticks<=0||a.completion_deadline_ticks<a.work_ticks||a.cash_limit<0||a.grain_limit<0||common.tick()<0||common.tick()>std::numeric_limits<Integer>::max()-a.completion_deadline_ticks)return {false,{},common_failure("InvalidGovernanceCommissionTiming",fact_id).error};
    // 先由S6证明本人当前可受领，才能透露该权源的已接受状态；仍保一个签发只能建立一个任务。
    for(const auto& row:governance.governance_contracts.rows())if(row.second.acceptance.authority_source_fact_id==fact_id)return {false,{},common_failure("GovernanceAuthorityAlreadyAccepted",fact_id).error};
    return approved;
}
Outcome<GovernanceTaskAcceptance> begin_governance_task(CommonStore& common,TaskState& tasks,GovernanceTaskState& governance,const CommonCatalog& catalog,const GovernanceAuthorityRead& authority,const StableId& executor,const StableId& fact_id,Integer expected_revision,const GovernanceReserveResources& reserve){
    auto quote=preview_governance_acceptance(common,governance,authority,executor,fact_id,expected_revision);if(!quote.ok)return {false,{},quote.error};if(!reserve)return {false,{},common_failure("MissingGovernanceReserveService",fact_id,ErrorKind::internal).error};const auto& approved=quote.value;const auto* name=catalog.texts.find(approved.rule_name_key);if(!name||name->empty())return {false,{},common_failure("UnknownGovernanceRuleText",approved.rule_name_key).error};
    const auto serial=common.state().next_instance_id;auto task_id=common.next_id("task");if(!task_id.ok)return {false,{},task_id.error};auto contract_id=common.next_id("governance_contract");if(!contract_id.ok)return {false,{},contract_id.error};auto action_id=common.next_id("action");if(!action_id.ok)return {false,{},action_id.error};auto acceptance_id=common.next_id("governance_accept");if(!acceptance_id.ok)return {false,{},acceptance_id.error};
    GovernanceTaskAcceptance accepted;accepted.fact_id=acceptance_id.value;accepted.task_id=task_id.value;accepted.contract_id=contract_id.value;accepted.authority_source_fact_id=fact_id;accepted.organization_id=approved.organization_id;accepted.executor_actor_id=executor;accepted.jurisdiction_id=approved.jurisdiction_id;accepted.site_id=approved.site_id;accepted.rule_id=approved.rule_id;accepted.rule_version=approved.rule_version;accepted.reservation_id=contract_id.value;accepted.display_name=*name;accepted.accepted_revision=common.revision();accepted.accepted_tick=common.tick();accepted.work_ticks=approved.work_ticks;accepted.deadline_tick=common.tick()+approved.completion_deadline_ticks;
    TaskRecord task;task.id=task_id.value;task.offer_id=fact_id;task.assignee=executor;task.status="active";task.serial=serial;task.accepted_tick=accepted.accepted_tick;task.deadline_tick=accepted.deadline_tick;
    if(!tasks.tasks.insert(task.id,task))return {false,{},common_failure("DuplicateGovernanceTask",task.id,ErrorKind::internal).error};GovernanceTaskContract contract;contract.acceptance=accepted;contract.action_id=action_id.value;if(!governance.governance_contracts.insert(task.id,contract))return {false,{},common_failure("DuplicateGovernanceContract",task.id,ErrorKind::internal).error};
    auto written=common.append_fact({accepted.fact_id,"governance_task_accepted","tasks"});if(!written.ok)return {false,{},written.error};GovernanceTaskRead read(common,tasks,governance);auto reserved=reserve(read,accepted,approved);if(!reserved.ok)return {false,{},reserved.error};const auto& terms=reserved.value;
    if(terms.id.empty()||terms.task_id!=accepted.task_id||terms.contract_id!=accepted.contract_id||terms.acceptance_fact_id!=accepted.fact_id||terms.authority_source_fact_id!=accepted.authority_source_fact_id||terms.jurisdiction_id!=accepted.jurisdiction_id||terms.site_id!=accepted.site_id||terms.organization_id!=accepted.organization_id||terms.public_wallet_id!=approved.public_wallet_id||terms.public_inventory_id!=approved.public_inventory_id||terms.item_id!=approved.grain_item_id||terms.reservation_id!=accepted.contract_id||terms.total_cash!=approved.cash_limit||terms.total_grain!=approved.grain_limit)return {false,{},common_failure("GovernanceReservationSourceMismatch",task.id,ErrorKind::internal).error};
    // SetReservation本身不检查足额，开工前反查真实同contract预留，不能只相信回调声称成功。
    const ReservationRef reservation{ReservationRef::Kind::contract,accepted.contract_id};const auto* wallet=common.wallet(terms.public_wallet_id);if(!wallet)return {false,{},common_failure("UnknownWallet",terms.public_wallet_id,ErrorKind::internal).error};Integer reserved_cash=0;bool found_cash=false;for(const auto& value:wallet->reserved)if(value.action_id==reservation){if(found_cash)return {false,{},common_failure("DuplicateGovernanceReservation",task.id,ErrorKind::internal).error};found_cash=true;reserved_cash=value.amount;}
    const auto available=common.spendable(terms.public_wallet_id);if(!available.ok)return {false,{},available.error};const auto goods=common.count(terms.public_inventory_id,terms.item_id,{{Owner::Kind::organization,terms.organization_id,{}}},reservation);if(!goods.ok)return {false,{},goods.error};
    if(reserved_cash!=terms.total_cash||goods.value!=terms.total_grain||available.value<0)return {false,{},common_failure("GovernanceReservationNotFunded",task.id,ErrorKind::internal).error};
    accepted.relief_terms_id=terms.id;governance.governance_contracts.find(task.id)->acceptance.relief_terms_id=terms.id;
    ActionCoreView action{action_id.value,"governance_appease",executor,{executor},common.tick(),approved.work_ticks};ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action=action;written=common.apply_action(insert);if(!written.ok)return {false,{},written.error};ActorMutation occupied;occupied.actor_id=executor;occupied.action_id=action.id;written=common.apply_actor(occupied);if(!written.ok)return {false,{},written.error};return {true,std::move(accepted),{}};
}
}
